const EPSILON = 1e-9;

const roundUpFavor = (amount: number): number => Math.ceil(amount - EPSILON);

const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const componentGroupBasePremium = (count: number): number => {
  if (count === 3) return 60;
  return count * 25;
};

const itemBasePremiums = (items: Item[]): number[] => {
  const premiums: number[] = [];
  const componentCounts = new Map<string, number>();
  for (const item of items) {
    if (COMPONENT_TYPES.has(item.type)) {
      componentCounts.set(item.type, (componentCounts.get(item.type) ?? 0) + 1);
    } else {
      premiums.push(MAIN_ITEM_BASE_PREMIUM[item.type]);
    }
  }
  for (const count of componentCounts.values()) {
    premiums.push(componentGroupBasePremium(count));
  }
  return premiums;
};

const quote = (step: QuoteStep): { premium: number } => {
  const basePremium = itemBasePremiums(step.items).reduce((a, b) => a + b, 0);
  const withFirstInsurance = basePremium * 1.1;
  return { premium: roundUpFavor(withFirstInsurance + PROCESSING_FEE) };
};

const EPSILON = 1e-9;

const roundUpFavor = (amount: number): number => Math.ceil(amount - EPSILON);

const MAIN_ITEM_BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

