import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Base premiums for single main items (base + 10% first insurance + 5G fee) ---
  it("empty item list -> premium 5 G (only processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });
    expect(result.results[0]).toEqual({ premium: 5 });
  });

  // --- Component pricing and building blocks ---
  it("2 runes -> base premium 50 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });
    // base 50 + 10% first insurance (5) + 5 fee = 60
    expect(result.results[0]).toEqual({ premium: 60 });
  });
  it("3 runes -> base premium 60 G (block applies)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] }],
    });
    // base 60 (block) + 10% (6) + 5 fee = 71
    expect(result.results[0]).toEqual({ premium: 71 });
  });
  it("4 runes -> base premium 100 G (no block, block requires exactly 3)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }] }],
    });
    // base 100 + 10% (10) + 5 fee = 115
    expect(result.results[0]).toEqual({ premium: 115 });
  });
  it("7 runes -> base premium 175 G", () => {
    const items = Array.from({ length: 7 }, () => ({ type: "rune" }));
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items }],
    });
    // base 175 + 10% (17.5) + 5 fee = 197.5 -> round up 198
    expect(result.results[0]).toEqual({ premium: 198 });
  });
  it("2 runes + 1 moonstone -> base premium 75 G (no block: different types)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }] }],
    });
    // base 75 + 10% (7.5) + 5 fee = 87.5 -> round up 88
    expect(result.results[0]).toEqual({ premium: 88 });
  });
  it.todo("3 runes + 3 moonstones -> base premium 120 G (two separate blocks)");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet -> 210 G before further modifiers and fee (curse on cursed item only)");

  // --- Modifier thresholds ---
  it.todo("customer with exactly 2 years -> loyalty discount applies");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");

  // --- Integration examples (full premium) ---
  it.todo("newcomer with cursed sword (steel, ench 3) -> premium 165 G");
  it.todo("long-standing customer's second contract: cursed sword (steel, ench 7) -> premium 160 G");

  // --- Rounding of premium ---
  it.todo("premium yielding 197.5 G -> final premium 198 G (rounded up, MHPCO favor)");

  // --- Standard claim reimbursement ---
  it.todo("regular sword (steel, ench 3), damage 500 G -> payout 400 G");
  it.todo("rune (value 250 G), damage 200 G -> payout 100 G");

  // --- Special claim clauses ---
  it.todo("dragon-material sword, ench 5, damage 800 G -> payout 700 G (dragon full reimbursement)");
  it.todo("steel sword, ench 9, damage 1000 G -> payout 400 G (high-enchantment 50% then deductible)");
  it.todo("dragon-material sword, ench 9, damage 1000 G -> payout 400 G (both clauses, 50% wins)");
  it.todo("dragon-material sword, exactly ench 8, damage 1000 G -> payout 400 G");

  // --- Deductible per damage event ---
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) -> payout 600 G (deductible once per item)");

  // --- Payout rounding ---
  it.todo("payout yielding 350.5 G -> final payout 350 G (rounded down, MHPCO favor)");

  // --- Multiple items of same type ---
  it.todo("policy covers two swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("dragon attack damages both swords (two entries) -> each treated as separate damage with own deductible");
  it.todo("more damage entries of a type than covered -> claim rejected (non-zero exit)");

  // --- Cap exhaustion ---
  it.todo("sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword (premium 165) -> cap 2000 G (based on unmodified insurance value)");
  it.todo("sword + 3 runes block -> insurance sum 1750 G (block discount affects premium only)");
  it.todo("sword cap 2000 G, two claims of 1500 G: first payout 1400 G remaining 600 G, second payout 600 G remaining 0 G");

  // --- Edge cases (CLI error handling) ---
  it.todo("quote with unknown item type -> non-zero exit, error to stderr, no results to stdout");
  it.todo("claim referencing item not in policy -> non-zero exit, error to stderr");
  it.todo("claim with negative damage amount -> non-zero exit, error to stderr");
});

