interface Policy {
  items: Item[];
  remainingCap: number;
}

const claimPayout = (damage: Damage): number => {
  return roundDownFavor(damage.amount - DEDUCTIBLE);
};

const claim = (step: ClaimStep, policy: Policy): { payout: number; remainingCap: number } => {
  const payout = step.incident.damages.reduce((sum, d) => sum + claimPayout(d), 0);
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  let quoteCount = 0;
  const policies: Policy[] = [];
  const results = scenario.steps.map((step) => {
    if (step.op === "quote") {
      const isFollowUp = quoteCount > 0;
      quoteCount += 1;
      policies.push({ items: step.items, remainingCap: 0 });
      return quote(step, scenario.customer, isFollowUp);
    }
    const policy = policies[step.policy];
    return claim(step, policy);
  });
  return { results };
};

